import{_ as n}from"./chunks/23.D6CSNN-a.js";import{_ as r}from"./chunks/1._Wu06lVH.js";import{_ as e}from"./chunks/0.xVPDiwtD.js";import{_ as s}from"./chunks/2.9ug2zROR.js";import{_ as l}from"./chunks/18.CAVYOoBk.js";import{_ as d}from"./chunks/0.B7TrDeTt.js";import{_ as h}from"./chunks/4.ZpmvUIOM.js";import{_ as c}from"./chunks/0.DyB7G7H5.js";import{_ as g}from"./chunks/9._7FszrLL.js";import{_ as i}from"./chunks/0.C_OEUMPL.js";import{_ as p}from"./chunks/11.DPtnPYcq.js";import{_ as m}from"./chunks/100.DMbJtyMU.js";import{_ as u}from"./chunks/community.BdKwbEUF.js";import{_ as b,C as f,o as y,c as _,ak as a,E as w}from"./chunks/framework.sbZkgmEx.js";const v="/projects/AiBlock/en/advanced-kit/assets/1.DSIVKc9w.webp",x="/projects/AiBlock/en/advanced-kit/assets/2.1.D-XFu27x.webp",k="/projects/AiBlock/en/advanced-kit/assets/2.1.CyEbwCJo.webp",P="/projects/AiBlock/en/advanced-kit/assets/2.2.NWV5D54d.webp",q="/projects/AiBlock/en/advanced-kit/assets/3.CcKFGOSC.webp",C="/projects/AiBlock/en/advanced-kit/assets/4.AUgq5_FW.webp",M=JSON.parse('{"title":"3.23 Firefly","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.23 Firefly.md","filePath":"docs/3.Creative Builds/3.23 Firefly.md"}'),z={name:"docs/3.Creative Builds/3.23 Firefly.md"};function B(j,t,A,T,S,F){const o=f("Pdf");return y(),_("div",null,[t[0]||(t[0]=a('<h1 id="_3-23-firefly" tabindex="-1">3.23 Firefly <a class="header-anchor" href="#_3-23-firefly" aria-label="Permalink to &quot;3.23 Firefly&quot;">​</a></h1><h2 id="_3-23-1-lesson-introduction" tabindex="-1">3.23.1 Lesson Introduction <a class="header-anchor" href="#_3-23-1-lesson-introduction" aria-label="Permalink to &quot;3.23.1 Lesson Introduction&quot;">​</a></h2><p>Centering on the bionic firefly robot project, this lesson explores coordinated programming across the light sensor, servo, and RGB light module. It delivers bionic behaviors where darkness triggers automatic wing flapping and lighting while daylight halts all operations. The content covers precision servo angle regulation and breathing light routines, applies ambient light threshold evaluation structures, and examines multi-device synchronization in bio-inspired robotics.</p><img loading="lazy" height="1662" width="1662" src="'+n+'" class="common_img" style="width:400px;"><h2 id="_3-23-2-learning-objectives" tabindex="-1">3.23.2 Learning Objectives <a class="header-anchor" href="#_3-23-2-learning-objectives" aria-label="Permalink to &quot;3.23.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Understand the operating principles of servos, distinguishing angular positioning from continuous motor rotation. Learn the biological mechanisms of insect bioluminescence. Consolidate threshold evaluation logic for light sensors.</p></li><li><p><strong>Skill Objectives</strong>: Connect the servo, RGB light module, and light sensor accurately. Program reciprocating servo sweeps to control wing flapping. Implement automated bionic behavior where ambient light thresholds trigger synchronized wing flapping and breathing lights.</p></li><li><p><strong>Thinking Objectives</strong>: Build an integrated systems control mindset uniting ambient sensing with synchronized multi-actuator responses. Develop precision awareness in position control versus speed control. Strengthen understanding of environmental adaptive intelligence.</p></li><li><p><strong>Application Objectives</strong>: Connect concepts to robotic joint servos, smart nightlights, and ambient mood lighting. Understand the educational and demonstrative value of bionic robotics. Stimulate enthusiasm for bioluminescence and light-controlled intelligent systems.</p></li></ol><h2 id="_3-23-3-preparation" tabindex="-1">3.23.3 Preparation <a class="header-anchor" href="#_3-23-3-preparation" aria-label="Permalink to &quot;3.23.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>180° block servo</p></li><li><p>RGB light module</p></li><li><p>Light sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-23-4-hands-on-project" tabindex="-1">3.23.4 Hands-On Project <a class="header-anchor" href="#_3-23-4-hands-on-project" aria-label="Permalink to &quot;3.23.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project of this lesson is the Firefly, delivering a bionic robot that automatically flaps its wings and illuminates in darkness while remaining dormant in daylight. The system adopts an architecture uniting light sensing with synchronized dual-actuator responses: the light sensor continuously samples ambient illumination, and when the value falls below a defined threshold, the controller triggers two synchronized outputs. The servo drives a linkage mechanism to flap the wings through small angular sweeps, while the RGB light module emits a yellow breathing fade to mimic rhythmic glowing. Both outputs start and stop in unison. When the ambient environment brightens, the system halts both actuators, replicating nocturnal insect behaviors.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),w(o,{src:"../../_static/shared/pdf/chapter_3/23.pdf"}),t[1]||(t[1]=a('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the RGB light module to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li><li><p>Connect the light sensor to port <strong>B</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1579" width="2406" src="'+v+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Light sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+x+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+k+'" class="common_img" style="width:800px;"><ul><li>Select <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+P+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="121" width="358" src="'+r+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Serves as the main loop container, continuously executing internal code after power-on initialization</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="111" width="360" src="'+s+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="77" src="'+e+'"></td><td style="text-align:left;">Executes only once after the device powers on, used to place startup logic such as hardware initialization and parameter configuration</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="93" width="815" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="53" width="80" src="'+d+'"></td><td style="text-align:left;">Reads the light intensity value from the light sensor on the designated port across a range of 0 to 100, where higher values indicate brighter illumination</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="88" width="708" src="'+h+'"></td><td style="text-align:center;"><img loading="lazy" height="71" width="80" src="'+c+'"></td><td style="text-align:left;">Controls the 180° block servo on the designated port to rotate at a custom speed for a specified duration, continuing immediately to subsequent blocks without waiting if non-delay mode is selected</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="811" src="'+g+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+i+'"></td><td style="text-align:left;">Directs the RGB light module on the designated port to activate a breathing fade effect in a selected color, with a customizable transition period</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="86" width="576" src="'+p+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="80" src="'+i+'"></td><td style="text-align:left;">Extinguishes the RGB light module on the designated port to cut off light output</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="491" width="430" src="'+q+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>Upon startup, the Firefly enters its initialized standby state. In the main loop, the controller continuously evaluates ambient conditions: when light intensity drops below 30 under dark conditions, the servo begins flapping the wings while the RGB light module activates breathing mode. Otherwise, all outputs stop.</p></li></ul><img loading="lazy" height="660" width="971" src="'+C+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+m+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1KQ-KBn3OmxCo6xKJkb7ZQZAuPW9brr5t?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-23-5-expansion-and-challenge" tabindex="-1">3.23.5 Expansion and Challenge <a class="header-anchor" href="#_3-23-5-expansion-and-challenge" aria-label="Permalink to &quot;3.23.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Multi-Colored Firefly Customization</strong></p><p>Use the left and right buttons to toggle RGB colors between green on the left button, blue on the right button, and default yellow, pairing each palette with unique breathing periods. Use a variable to track the active color state and update the variable upon button presses. Practice using state variables within multi-branch conditional statements to understand parametric control, extending discussions to color variations in bioluminescent species and the underlying biochemistry.</p><p><strong>Project 2: Sound-Activated Interactive Firefly</strong></p><p>Maintain gentle breathing fades and slow wing flapping under normal conditions, and program clapping sounds to trigger rapid flashing and agitated wing flapping to simulate a biological startle response. Have the robot automatically return to steady state after several seconds. Practice transitioning between normal and triggered states alongside timed recovery routines, extending discussions to biological reflex arcs and emotional expression in interactive robotics.</p><h2 id="_3-23-6-q-a" tabindex="-1">3.23.6 Q&amp;A <a class="header-anchor" href="#_3-23-6-q-a" aria-label="Permalink to &quot;3.23.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Why does the Firefly program evaluate ambient light intensity, and why not keep the lights active during daylight?</strong></p><p>Answer: This mechanism replicates the <strong>nocturnal behavioral patterns</strong> of real fireflies, which stay dormant during daylight hours and become active only after dusk. Incorporating a light sensor to detect darkness conserves power while producing authentic biological simulations. In engineering, this approach represents <strong>environment-adaptive control</strong>, allowing devices to operate autonomously according to ambient conditions without manual switching. Common real-world applications including automated streetlights, smartphone ambient display brightness adjustment, and solar path lights rely on identical sensing principles to save energy and enhance operational convenience.</p><p><strong>Question 2: How does a breathing light gradually brighten and dim rather than switching abruptly between on and off?</strong></p><p>Answer: The breathing light operates via <strong>pulse width modulation, also known as PWM</strong>. Rather than altering the continuous supply voltage, the controller rapidly pulses the light on and off at speeds imperceptible to human vision. When the duration of the on state exceeds the off state within each cycle, the LED appears bright. Conversely, shortening the on duration causes the LED to appear dim. By progressively adjusting this duty cycle ratio from 0 to peak brightness and then lowering it back to 0, the program generates a smooth breathing curve. Unlike harsh instant on-and-off switching, smooth transitions provide a gentle visual experience, making PWM breathing indicators standard across smartphone notifications, sleep indicators, and automotive ambient lighting.</p><h2 id="_3-23-7-technical-support-and-product-discussion" tabindex="-1">3.23.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-23-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.23.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+u+'" class="common_img" style="width:800px;"></a>',33))])}const Q=b(z,[["render",B]]);export{M as __pageData,Q as default};
